        {
            if (int.TryParse(inputTextBox.Text, out int number))
            {
                if (number >= 0)
                {
                    try
                    {
                        long factorial = CalculateFactorial(number);
                        resultLabel.Text = $"The factorial of {number} is {factorial}.";
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show(ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                }
                else
                {
                    MessageBox.Show("Please enter a non-negative integer.", "Invalid Input", MessageBoxButtons.OK, MessageBoxIcon.Warning);
