// src/routes.ts
import { Router } from 'express';
import { getDb } from './db';

const router = Router();

router.get('/notes', async (req, res) => {
  const db = await getDb();
  const notes = await db.all('SELECT * FROM notes');
  res.json(notes);
});

router.post('/notes', async (req, res) => {
  const db = await getDb();
  const note = req.body;
  await db.run('INSERT INTO notes (title, content) VALUES (?, ?)', [note.title, note.content]);
  res.sendStatus(201);
});

router.put('/notes/:id', async (req, res) => {
  const db = await getDb();
  const id = req.params.id;
  const note = req.body;
  await db.run('UPDATE notes SET title = ?, content = ? WHERE id = ?', [note.title, note.content, id]);
  res.sendStatus(200);
});

router.delete('/notes/:id', async (req, res) => {
  const db = await getDb();
  const id = req.params.id;
  await db.run('DELETE FROM notes WHERE id = ?', [id]);
  res.sendStatus(200);
});

export { router };

