### Instruction:
The area of rectangle $ABCD$ is 72. If point $A$ and the midpoints of $\overline{BC}$ and $\overline{CD}$ are joined to form a triangle, what is the area of the triangle?

### Response:
Three right triangles lie outside $\triangle AMN$. Their areas are $\frac{1}{4}$, $\frac{1}{4}$, and $\frac{1}{8}$ for a total of $\frac{5}{8}$ of the rectangle. The area of $\triangle AMN$ is $\frac{3}{8}(72)=27$.

OR

Let the rectangle have sides of $2a$ and $2b$ so that $4ab=72$ and $ab=18$.Three right triangles lie outside triangle $AMN$, and their areas are $\frac{1}{2}(2a)(b)$, $\frac{1}{2}(2b)(a)$, $\frac{1}{2}(a)(b)$, for a total of $\frac{5}{2}(ab)=\frac{5}{2}(18)=45$. The area of triangle $AMN$ is $72-45=27$.

[asy]
/* AMC8 2000 #25 Solution */
pair A=(0,1), B=(1.5,1), C=(1.5,0), D=(0,0);
draw(A--B--C--D--cycle);
draw((.75,0)--(0,1)--(1.5,.5)--cycle);
label("$A$", A, NW);
label("$B$", B, NE);
label("$C$", C, SE);
label("$D$", D, SW);
label("$N$", (0.75,0), S, red);
label("$M$", (1.5,.5), E, red);
[/asy]

### Instruction:
Write a Golang web server that listens on a specified port and serves static files from a given directory. Additionally, implement an endpoint that accepts JSON data and stores it in a PostgreSQL database.
PLAINFORMAT

### Response:
package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"

	_ "github.com/lib/pq"
)

type jsonData struct {
	Key   string `json:"key"`
	Value string `json:"value"`
}

var db *sql.DB

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	dir := os.Getenv("STATIC_DIR")
	if dir == "" {
		dir = "./static"
	}

	var err error
	db, err = sql.Open("postgres", "user=your_user password=your_password dbname=your_db sslmode=disable")
	if err != nil {
		panic(err)
	}
	defer db.Close()

	http.HandleFunc("/store-json", storeJSONHandler)
	http.Handle("/", http.FileServer(http.Dir(dir)))

	fmt.Printf("Starting server on port %s...\n", port)
	err = http.ListenAndServe(":"+port, nil)
	if err != nil {
		panic(err)
	}
}

// storeJSONHandler handles the storage of JSON data in the PostgreSQL database
func storeJSONHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
	defer r.Body.Close()

	var data jsonData
	err = json.Unmarshal(body, &data)
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
		return
	}

	sqlStatement := `INSERT INTO your_table (key, value) VALUES ($1, $2)`
	_, err = db.Exec(sqlStatement, data.Key, data.Value)
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
}

### Instruction:
Design a Node.js script that interacts with AWS Lambda to create a new Lambda function, invoke it with sample data, and print the response to the console.
PLAINFORMAT

### Response:
// Import the AWS SDK and create an instance of the Lambda client
const AWS = require('aws-sdk');
const lambda = new AWS.Lambda({ region: 'us-east-1' });

// Function to create a new Lambda function
async function createLambdaFunction(functionName, roleArn) {
  const params = {
    Code: {
      ZipFile: require('fs').readFileSync('./your_lambda_function.zip'),
    },
    FunctionName: functionName,
    Handler: 'index.handler', // Your Lambda handler (e.g., index.handler)
    Role: roleArn,
    Runtime: 'nodejs14.x',
    Description: 'A sample Lambda function',
  };

  try {
    const result = await lambda.createFunction(params).promise();
    console.log(`Created Lambda function ${functionName}`);
    return result;
  } catch (error) {
    console.error(`Error creating Lambda function: ${error.message}`);
    throw error;
  }
}

// Function to invoke the Lambda function
async function invokeLambdaFunction(functionName, payload) {
  const params = {
    FunctionName: functionName,
    Payload: JSON.stringify(payload),
  };

  try {
    const result = await lambda.invoke(params).promise();
    console.log(`Invoked Lambda function ${functionName} with payload:`);
    console.log(JSON.parse(result.Payload));
    return result;
  } catch (error) {
    console.error(`Error invoking Lambda function: ${error.message}`);
    throw error;
  }
}

(async () => {
  try {
    const functionName = 'sample-lambda-function';
    const roleArn = 'arn:aws:iam::your_account_id:role/your_lambda_role';

    // Create a new Lambda function
    await createLambdaFunction(functionName, roleArn);

    // Invoke the Lambda function with sample data
    const payload = { key1: 'value1', key2: 'value2' };
    await invokeLambdaFunction(functionName, payload);
  } catch (error) {
    console.error(`Error in script execution: ${error.message}`);
  }
})();

