### Instruction:
Develop a JavaScript function that takes two arrays as input and returns a new array containing the elements present in both input arrays without duplicates. Optimize the function for performance.
PLAINFORMAT

### Response:
function intersection(arr1, arr2) {
  // Create sets from input arrays to remove duplicates within each array
  const set1 = new Set(arr1);
  const set2 = new Set(arr2);

  // Filter elements of the first set by checking if they are also present in the second set
  return [...set1].filter(item => set2.has(item));
}

// Example usage:
const arr1 = [1, 2, 3, 4, 5];
const arr2 = [3, 4, 5, 6, 7];

console.log(intersection(arr1, arr2)); // Output: [3, 4, 5]
